result = Broker.CALCULATE(
    num_distinct_customers=COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com')
            & HAS(
                transactions_made.WHERE(
                    ISIN(ticker.symbol, ('AMZN', 'AAPL', 'GOOGL', 'META', 'NFLX'))
                )
            )
        )
    )
)

tac_by_country = Customers.WHERE(
    join_date >= DATETIME("2023-01-01")
).PARTITION(
    name="country_group", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

result = Broker.CALCULATE(
    num_matching_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)
